package session

import (
	"fmt"
	"os"
	"path/filepath"
	"time"

	"github.com/sloprail/harness-mocks/internal/subagents"
)

// Child is where a sub-agent's records go: a rollout of its own, next to the
// session's in the same day directory and named like it, by the sub-agent's own
// thread id (recorded: runs/subagent-transcripts-v2).
type Child struct {
	// ID is the sub-agent's thread id.
	ID string
	// Path is the name the sub-agent gives itself in its parent's tree of
	// agents: /root/<task name>.
	AgentPath string
	Depth     int
}

// CreateChild starts the rollout of the sub-agent c that the session whose
// rollout is parent dispatched, beside the parent's and not in it. Its meta
// record is where the sub-agent is described: its thread id, the session
// it belongs to (session_id stays the parent's), the thread that spawned it
// and its depth and path in the tree of agents. Codex keeps no sidecar file, and
// the meta record names no tool call and no agent type beyond a role that was
// null in the recording.
//
// sr:provides subagent-transcripts/codex
func CreateChild(parent *File, parentID string, c Child, cwd string, now time.Time) (*File, error) {
	layout := subagents.Layout{SessionExt: ".jsonl", Ext: ".jsonl",
		Prefix: "rollout-" + now.Format("2006-01-02T15-04-05") + "-"}
	path := layout.Path(parent.Path, c.ID)
	f, err := os.Create(path)
	if err != nil {
		return nil, fmt.Errorf("sub-agent rollout %s: %w", filepath.Base(path), err)
	}
	s := &File{Path: path, f: f}
	s.append("session_meta", map[string]any{"id": c.ID, "session_id": parentID, "parent_thread_id": parentID,
		"cwd": cwd, "originator": "codex_exec", "cli_version": "mock", "thread_source": "subagent",
		"agent_path": c.AgentPath,
		"source": map[string]any{"subagent": map[string]any{"thread_spawn": map[string]any{
			"parent_thread_id": parentID, "depth": c.Depth, "agent_path": c.AgentPath, "agent_role": nil}}}})
	return s, nil
}

// Task records the task a sub-agent was given, as Codex words it for it.
func (s *File) Task(agentPath, text string) {
	s.append("response_item", map[string]any{"type": "agent_message", "content": []map[string]string{{"type": "input_text",
		"text": fmt.Sprintf("Message Type: NEW_TASK\nTask name: %s\nSender: /root\nPayload:\n%s", agentPath, text)}}})
}

