)

// spawnTool is the tool with which the agent dispatches a sub-agent.
const spawnTool = "spawn_agent"

// spawnAgent carries out the agent's spawn_agent call: the call and its answer
// are the session's records, and the sub-agent's own, the task it was given,
// go to a rollout of its own (recorded: runs/subagent-transcripts-v2). The
// mock runs no turn of the sub-agent: it records the task and nothing of what
// the sub-agent would do with it.
func (h turnHost) spawnAgent(_ context.Context, tu scenario.ToolUse) {
	h.rollout.ToolCall(tu.ID, tu.Name, tu.Input)
	var in struct {
		TaskName string `json:"task_name"`
		Message  string `json:"message"`
	}
	_ = json.Unmarshal(tu.Input, &in)
	place := subagents.Place(subagents.Parent{})
	child := session.Child{ID: coresession.NewID(), AgentPath: "/root/" + in.TaskName, Depth: place.Depth}
	f, err := session.CreateChild(h.rollout, h.id, child, h.cfg.Cwd, time.Now())
	if err != nil {
		h.rollout.ToolOutput(tu.ID, err.Error())
		return
	}
	defer f.Close()
	f.Task(child.AgentPath, in.Message)
	out, _ := json.Marshal(map[string]string{"task_name": child.AgentPath})
	h.rollout.ToolOutput(tu.ID, string(out))
}

