	_ = json.Unmarshal(tu.Input, &in)
	prompt, _ := in["prompt"].(string)
	call := toolexec.Call{Kind: "taskToolCall", Args: map[string]any{"description": in["description"], "prompt": prompt}}
	s.forward(startedFrame(s.id, tu.ID, call))
	s.tr.toolUse(tu.Name, in)

	id := coresession.NewID()
	child := &transcript{path: cursorSubagentLayout.Path(s.tr.path, id)}
	result := map[string]any{"success": map[string]any{"agentId": id, "isBackground": false}}
	if err := os.MkdirAll(filepath.Dir(child.path), 0o755); err != nil {
		result = map[string]any{"error": map[string]any{"errorMessage": err.Error()}}
	} else {
		child.user(prompt)
		child.end()
	}
	s.forward(completedFrame(s.id, tu.ID, call, result))
}

