// cursorSubagentLayout is where Cursor keeps a sub-agent's transcript: a
// directory and a file of its own, named by its own id, next to the session's
// directory under agent-transcripts, so it is a conversation like any other
// there and not a part of the session's. Cursor keeps no file that says what
// type of sub-agent it is, which call spawned it or how deep it is
// (recorded: runs/subagent-transcripts).
var cursorSubagentLayout = subagents.Beside{Ext: ".jsonl", OwnDir: true}

// task carries out a Task call that passed validation: what the sub-agent was
// asked goes to a transcript of its own, and the call's result, on the
// stream, names the sub-agent by the id of that transcript (the session's own
// transcript holds the call, which toolUse recorded). The mock runs no turn of
// the sub-agent: it records the task and nothing of what the sub-agent would
// do with it.
//
// sr:provides subagent-transcripts/cursor
func (s *session) task(c toolexec.Call) toolexec.Result {
	prompt, _ := c.Args["prompt"].(string)
	id := coresession.NewID()
	child := &transcript{path: cursorSubagentLayout.Path(s.tr.path, id)}
	if err := os.MkdirAll(filepath.Dir(child.path), 0o755); err != nil {
		return toolexec.Result{Failed: true, ErrorMessage: err.Error(),
			Frame: map[string]any{"error": map[string]any{"errorMessage": err.Error()}}}
	}
	child.user(prompt)
	child.end()
	out, _ := json.Marshal(map[string]any{"agentId": id})
	return toolexec.Result{Frame: map[string]any{"success": map[string]any{"agentId": id, "isBackground": false}},
		ToolOutput: string(out)}
}

