package subagents

import "path/filepath"

// Beside is where a harness with no sub-agent directory keeps a sub-agent's
// transcript: with the session's, not in it.
type Beside struct {
	// Prefix and Ext name the file: <Prefix><sub-agent id><Ext>.
	Prefix, Ext string
	// OwnDir puts the file in a directory named by the sub-agent's id, next to
	// the session's directory; otherwise it sits next to the session's file.
	OwnDir bool
}

// Path is the transcript of sub-agent id for a session whose transcript is
// sessionFile: a file of its own, never the session's.
//
// sr:capability subagent-transcripts
func (b Beside) Path(sessionFile, id string) string {
	dir := filepath.Dir(sessionFile)
	if b.OwnDir {
		dir = filepath.Join(filepath.Dir(dir), id)
	}
	return filepath.Join(dir, b.Prefix+id+b.Ext)
}

